ACTIVATE USL TABLE lightning.metastore.jedi_pack.jedi_pack.customer AS SELECT COALESCE(sender_email, '') AS email, MAX(sender_name) AS name FROM (SELECT sender_email, sender_name FROM JEDI_PACK.threads_json UNION ALL SELECT sender_email, sender_name FROM JEDI_PACK.intake_runtime) u WHERE sender_email IS NOT NULL AND sender_email <> '' GROUP BY sender_email;
ACTIVATE USL TABLE lightning.metastore.jedi_pack.jedi_pack.ticket AS SELECT COALESCE(thread_id, '') AS thread_id, parent_thread_id, channel, category, agent_category, sender_name, sender_email, subject, body, follow_up_kind, received_at, CAST(amount_usd AS double) AS amount_usd, may_leave, CAST(owner_id AS int) AS owner_id, CAST(backup_id AS int) AS backup_id, outcome, 'parquet' AS data_source FROM JEDI_PACK.threads_parquet;
